const input = $input.first();
const raw = (input && input.json) || {};
const body = raw.body || raw;

// Fix: Detect trigger source dựa vào cấu trúc payload, không dùng try/catch node check
// Webhook payload sẽ có raw.headers hoặc raw.body object rõ ràng
// ExecuteWorkflow payload sẽ có params hoặc issueKey trực tiếp
let triggerSource = 'mattermost';
if (raw.headers || (raw.body && typeof raw.body === 'object')) {
  triggerSource = 'webhook';
} else if (raw._triggerSource) {
  triggerSource = raw._triggerSource;
}

const params = body.params || raw.params || {};
let issueKey = body.issueKey || raw.issueKey || params.issueKey || "";
let project = body.project || raw.project || params.project || "";
const userName = body.user_name || body.userName || raw.userName || "User";

const text = body.text || raw.text || "";
if (!issueKey && text) {
  const match = text.match(/\b([A-Za-z0-9]+-[0-9]+)\b/i);
  if (match) issueKey = match[1].toUpperCase();
}

const isLegacyBatch = Array.isArray(body.testCases) && body.testCases.length > 0;

return [{
  json: {
    issueKey,
    project,
    targetPath: "test",
    userName,
    isLegacyBatch,
    testCases: body.testCases || [],
    baseUrl: body.baseUrl || "",
    apiToken: body.apiToken || "",
    folderId: body.folderId || "",
    projectId: body.projectId || "",
    _triggerSource: triggerSource
  }
}];

const { exec } = require('child_process');
const util = require('util');
const fs = require('fs');
const path = require('path');
const execAsync = util.promisify(exec);

const input = $input.first();
const resolveRes = input.json || {};
const context = $('Extract & Prepare Input').first()?.json || {};
const issueKey = context.issueKey || resolveRes.issueKey || '';
const project = context.project || resolveRes.project || '';
const triggerSource = context._triggerSource || context.triggerSource || 'mattermost';
const userName = context.userName || 'User';

if (!issueKey) {
  return [{
    json: {
      success: false,
      isError: true,
      reportText: '🚨 **[Squash Push Lỗi]** Không tìm thấy mã `issueKey` trong yêu cầu.\n> Cú pháp: `/agent [project] push-squash <issueKey>`',
      _triggerSource: triggerSource,
      userName
    }
  }];
}

if (resolveRes.isError || !resolveRes.found) {
  const errMsg = resolveRes.reportText || `Không tìm thấy thư mục workspace cho ticket **${issueKey}**.`;
  return [{
    json: {
      success: false,
      isError: true,
      reportText: `🚨 **[Squash Push Lỗi]** ${errMsg}`,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

const projectRoot = resolveRes.projectRoot || (($env && $env.AGENT_WORKSPACE_DIR) || '/Users/qa-quangnt/Desktop/Project/Test/agent-skills');
const matchedFiles = resolveRes.matchedFiles || [];
const featureFile = matchedFiles.find(f => f.endsWith('.feature'));

if (!featureFile) {
  return [{
    json: {
      success: false,
      isError: true,
      reportText: `🚨 **[Squash Push Lỗi]** Không tìm thấy file kịch bản BDD (\`.feature\`) trong thư mục test của ticket **${issueKey}**.\n> Đường dẫn tìm kiếm: \`${resolveRes.targetPath || 'workspace/' + issueKey + '/test'}\`\n*👉 Hãy chạy kỹ năng \`qa-auto-design\` hoặc tạo file \`${issueKey}.feature\` trước khi đẩy lên Squash TM.*`,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

// Tìm namejira từ final.md nếu có
let namejira = issueKey;
const finalMdPath = path.join(projectRoot, 'workspace', issueKey, 'spec', 'final.md');
if (fs.existsSync(finalMdPath)) {
  try {
    const finalContent = fs.readFileSync(finalMdPath, 'utf-8');
    const firstLine = finalContent.split('\n').find(l => l.startsWith('# '));
    if (firstLine) {
      namejira = firstLine.replace(/^#\s*(\[[^\]]+\])?\s*/, '').trim()
        .replace(/[^a-zA-Z0-9\u00C0-\u024F\u1EA0-\u1EF9]+/g, '-')
        .replace(/^-+|-+$/g, '').substring(0, 80);
    }
  } catch (_) {}
}

// Xác định đường dẫn script engine squash-push.sh từ repo agent-skills
const agentSkillsRoot = ($env && $env.AGENT_WORKSPACE_DIR) || '/Users/qa-quangnt/Desktop/Project/Test/agent-skills';
const scriptCandidates = [
  path.join(agentSkillsRoot, 'plugins/qa/skills/qa-squash-push/assets/squash-push.sh'),
  '/Users/qa-quangnt/Desktop/Project/Test/agent-skills/plugins/qa/skills/qa-squash-push/assets/squash-push.sh',
  path.join(projectRoot, 'plugins/qa/skills/qa-squash-push/assets/squash-push.sh')
];

let scriptPath = '';
for (const cand of scriptCandidates) {
  if (fs.existsSync(cand)) {
    scriptPath = cand;
    break;
  }
}

if (!scriptPath) {
  return [{
    json: {
      success: false,
      isError: true,
      reportText: `🚨 **[Squash Push Lỗi]** Không tìm thấy script engine \`squash-push.sh\` tại các thư mục plugins:\n` +
                  scriptCandidates.map(c => `- \`${c}\``).join('\n'),
      _triggerSource: triggerSource,
      userName
    }
  }];
}

const absFeatureFile = path.isAbsolute(featureFile) ? featureFile : path.join(projectRoot, featureFile);
const cmd = `bash "${scriptPath}" "${issueKey}" "${namejira || issueKey}" "${absFeatureFile}"`;

try {
  const result = await execAsync(cmd, {
    cwd: projectRoot,
    timeout: 180000,
    encoding: 'utf-8',
    env: { ...require('process').env }
  });

  const stdout = result.stdout || '';

  // Đọc file sync metadata nếu có
  let syncMeta = null;
  const syncJsonPath = path.join(projectRoot, 'workspace', issueKey, 'test', 'squash_sync.json');
  if (fs.existsSync(syncJsonPath)) {
    try {
      syncMeta = JSON.parse(fs.readFileSync(syncJsonPath, 'utf-8'));
    } catch (_) {}
  }

  return [{
    json: {
      success: true,
      isError: false,
      issueKey,
      project,
      featureFile: absFeatureFile,
      namejira,
      stdout,
      syncMeta,
      _triggerSource: triggerSource,
      userName
    }
  }];
} catch (err) {
  const errOutput = (err.stdout || '') + '\n' + (err.stderr || err.message || '');
  return [{
    json: {
      success: false,
      isError: true,
      issueKey,
      project,
      featureFile: absFeatureFile,
      errorOutput: errOutput,
      reportText: `🚨 **[Squash Push Thất Bại]** Không thể đồng bộ kịch bản Gherkin của **${issueKey}** lên Squash TM:\n\`\`\`text\n${errOutput.substring(errOutput.length - 1200)}\n\`\`\``,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

const input = $input.first();
const res = (input && input.json) || {};

if (res.isError) {
  return [{ json: res }];
}

const meta = res.syncMeta || {};
const issueKey = res.issueKey || '';
const featureFile = res.featureFile || '';
const tcId = meta.testCaseId;
const tcName = meta.testCaseName || `${issueKey}-${res.namejira}`;
const sprintName = meta.sprintName || 'Sprint mới nhất';
const sprintReqId = meta.sprintReqVersionId;
const baseUrl = (($env && $env.SQUASH_BASE_URL) || 'https://tm.dnse.com.vn/squash').replace(/\/+$/, '');

const tcLink = tcId ? `[#${tcId} - ${tcName}](${baseUrl}/test-case-workspace/test-case/${tcId})` : `\`${tcName}\``;
const campaignStatus = sprintReqId 
  ? `✅ **Đã gán vào Requirement Test Plan** (sprint-req-version: \`#${sprintReqId}\`)` 
  : `⚠️ *Chưa tìm thấy Requirement tương ứng trong Sprint để tự động gán*`;

const reportText = `### 🧪 Kết Quả Đẩy Kịch Bản Gherkin Lên Squash TM
- **Ticket:** **${issueKey}** ${res.project ? '(`' + res.project + '`)' : ''}
- **Kịch bản nguồn:** \`${featureFile}\`
- **Thư mục Sprint:** \`${sprintName}\`
- **Test Case Workspace:** ${tcLink}
- **Nội dung BDD:** ✅ Đã nạp toàn bộ kịch bản Gherkin (.feature) vào trường script.
- **Campaign Workspace:** ${campaignStatus}
- **Truy vết Local:** Đã lưu metadata tại \`workspace/${issueKey}/test/squash_sync.json\``;

return [{
  json: {
    ...res,
    reportText
  }
}];

const input = $input.first().json || {};
const testCases = input.testCases || [];
const baseUrl = (input.baseUrl || ($env && $env.SQUASH_BASE_URL) || "").replace(/\/$/, "");
const apiToken = input.apiToken || ($env && $env.SQUASH_API_TOKEN) || "";
const folderId = input.folderId || ($env && $env.SQUASH_TC_G31_FOLDER_ID);
const projectId = input.projectId || ($env && $env.SQUASH_PROJECT_ID);
const triggerSource = input._triggerSource || "webhook";

if (testCases.length === 0) {
  return [{
    json: {
      isEmpty: true,
      baseUrl, apiToken, folderId, projectId,
      _triggerSource: triggerSource
    }
  }];
}

return testCases.map(tc => ({
  json: {
    baseUrl, apiToken, folderId, projectId,
    name: tc.name || "Test Case",
    reference: tc.reference || "",
    description: tc.description || "",
    prerequisite: tc.prerequisite || "",
    _triggerSource: triggerSource
  }
}));

const results = $input.all();
const first = results[0] ? results[0].json : {};
const triggerSource = first._triggerSource || "webhook";

if (first.isEmpty) {
  return [{
    json: {
      status: "error",
      isError: true,
      totalImported: 0,
      reportText: "⚠️ **[Squash Batch Pusher]** Không tìm thấy danh sách test cases nào trong payload để đẩy lên Squash TM.",
      _triggerSource: triggerSource
    }
  }];
}

const errors = [];
const createdCases = [];

for (const r of results) {
  const j = r.json || {};
  if (j.error || (j.status && j.status >= 400)) {
    errors.push((j.error && (j.error.message || j.error.description)) || j.message || "Lỗi HTTP " + j.status);
  } else if (j.id) {
    createdCases.push({ id: j.id, name: j.name || "" });
  }
}

const isError = errors.length > 0;
let reportText = "";
if (isError && createdCases.length === 0) {
  reportText = "🚨 **[Lỗi Đẩy Test Case Squash TM]** Không thể tạo test case nào lên hệ thống:\n> " + errors[0];
} else if (isError && createdCases.length > 0) {
  reportText = "⚠️ **[Cảnh Báo Squash TM]** Đã tạo thành công **" + createdCases.length + "** test cases, nhưng có **" + errors.length + "** test cases thất bại.\n> Lỗi mẫu: " + errors[0];
} else {
  reportText = "### 🧪 Batch Push Squash TM Hoàn Tất\n- **Tổng số test case đã tạo:** " + createdCases.length + "\n- **Trạng thái:** ✅ Thành công 100%";
}

return [{
  json: {
    status: isError ? (createdCases.length > 0 ? "partial" : "failed") : "success",
    isError: isError,
    totalImported: createdCases.length,
    failedCount: errors.length,
    createdCases: createdCases,
    errors: errors,
    reportText: reportText,
    _triggerSource: triggerSource
  }
}];
